~~~go
func fibonacci(n int) (uint64, error) {
    if n < 0 { return 0, errors.New("negative index") }
    var a, b uint64 = 0, 1
    for i := 0; i < n; i++ {
        if math.MaxUint64-b < a { return 0, errors.New("overflow") }
        a, b = b, a+b
    }
    return a, nil
}
~~~

